Method.Source:
    /// <summary>
    /// MPJ_4050_CustomerPaymentsOpen
    /// </summary>
    /// <param name = "metCustTable">
    /// get the table buffer
    /// </param>
    /// <returns>
    /// wreturn MainContactWorker worker 
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display Name getMETMainContactWorker(CustTable   metCustTable)
    {
        Name            metMainContactWorker;
        HcmWorker       metHcmWorker;
        DirPersonName   metDirPersonName;
        DirPartyTable   metDirPartyTable;

        select firstonly MainContactWorker from metCustTable
            join RecId from metHcmWorker
                where metHcmWorker.RecId == metCustTable.MainContactWorker
            join Person from metDirPersonName
                where metDirPersonName.Person == metHcmWorker.Person
            join RecId,Name from metDirPartyTable
                where metDirPartyTable.RecId == metDirPersonName.Person;

        return  metMainContactWorker;
    }
